parameters.jsCode:
const item = $input.first().json;
const body = item.body || item;

const email = String(body.email || body['Corporate / Developer Email'] || '').trim().toLowerCase();
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!email || !emailRegex.test(email)) {
  throw new Error('Validation Failed: Invalid developer/work email address: ' + email);
}

const name = String(body.name || body['Your Name / Organization'] || 'Engineer').trim();
const projectName = String(body.projectName || body['Project Name'] || 'AI Architecture Project').trim();
const githubUrl = String(body.githubUrl || body['GitHub Profile or Project Repository URL'] || '').trim();
const category = String(body.category || body['Collaboration Category'] || 'Enterprise AI Deployment').trim();
const scope = String(body.scope || body['Technical Challenges & Deployment Scope'] || '').trim();
const submissionId = 'FDE-' + Date.now().toString().slice(-6);

const telegram_msg = '🎯 *New FDE Collaboration Intake Captured!*\n\n' +
  '👤 *Submitter:* ' + name + '\n' +
  '📧 *Email:* `' + email + '`\n' +
  '💼 *Category:* ' + category + '\n' +
  '🚀 *Project:* ' + projectName + '\n' +
  '🔗 *GitHub:* ' + (githubUrl || 'Confidential / Under NDA') + '\n\n' +
  '📝 *Scope:* ' + scope.slice(0, 250) + '\n\n' +
  '⚡ *Receipt:* ' + submissionId + ' | 24h SLA Dispatched';

return [{
  json: {
    submissionId,
    name,
    email,
    projectName,
    githubUrl,
    category,
    scope,
    telegram_msg,
    received_at: new Date().toISOString()
  }
}];

